-- CHAMBER-GAP SWEEP ON THIS WAVE'S OWN OUTPUT
-- Rule 30's second corollary: a measure whose `chamber` does not appear among its own
-- roll calls is almost always an ingest gap. Applied to this wave's OWN output rather
-- than only to the existing corpus, because a wave aimed at a chamber gap is the
-- easiest place to create one.
--   H.J.Res. 140 is a House measure. Its House passage roll (119/2/38) is admitted
--   alongside its Senate passage roll (119/2/84) for exactly this reason. S.J.Res. 7 is
--   a Senate measure with a Senate roll and no House action of any kind — govinfo
--   returns 302 for its eh and enr texts — so it has no gap to close.
--   Both new measures have at least one roll call in their own chamber. The verification
--   block in the migration asserts this per measure rather than trusting it.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  rc integer;
  m_119_s_j_res_7 integer;
  m_119_h_j_res_140 integer;
BEGIN
  -- ── measures ──────────────────────────────────────────────────────────────
  -- Every lookup keys on measure_type, congress, chamber AND number, and creation is
  -- guarded on IF ... IS NULL: federal (measure_type, congress, chamber, number) has no
  -- unique index, so a bare INSERT duplicates the measure on a second run and splits its
  -- rolls across two ids. H.J.Res. 140 is declared once here and carries two rolls.

  -- S.J.Res. 7 (119th senate) — NEW
  --   status passed_senate, introduced 2025-01-27
  SELECT id INTO m_119_s_j_res_7 FROM vr_measures
   WHERE measure_type = 'resolution' AND congress = 119
     AND chamber = 'senate' AND number = 'S.J.Res. 7' LIMIT 1;
  IF m_119_s_j_res_7 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('resolution', 119, 'senate', 'S.J.Res. 7', 'A joint resolution providing for congressional disapproval under chapter 8 of title 5, United States Code, of the rule submitted by the Federal Communications Commission relating to "Addressing the Homework Gap Through the E-Rate Program"', 'Disapproving the FCC E-Rate Wi-Fi hotspot rule',
      NULL, DATE '2025-01-27', 'passed_senate',
      'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/7', 'Congress.gov', '{"billType":"sjres","billNumber":7,"congress":119,"govinfoText":"BILLS-119sjres7es","disapprovedRule":"89 FR 67303"}'::jsonb)
    RETURNING id INTO m_119_s_j_res_7;
  END IF;
  IF m_119_s_j_res_7 IS NULL THEN
    RAISE EXCEPTION 'Federal wave F3: S.J.Res. 7 could not be created or read back.';
  END IF;

  -- H.J.Res. 140 (119th house) — NEW
  --   status enacted, introduced 2026-01-12
  SELECT id INTO m_119_h_j_res_140 FROM vr_measures
   WHERE measure_type = 'resolution' AND congress = 119
     AND chamber = 'house' AND number = 'H.J.Res. 140' LIMIT 1;
  IF m_119_h_j_res_140 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('resolution', 119, 'house', 'H.J.Res. 140', 'Providing for congressional disapproval under chapter 8 of title 5, United States Code, of the rule submitted by the Bureau of Land Management relating to Public Land Order No. 7917 for Withdrawal of Federal Lands; Cook, Lake, and Saint Louis Counties, MN', 'Disapproving the BLM Boundary Waters mineral withdrawal',
      NULL, DATE '2026-01-12', 'enacted',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/140', 'Congress.gov', '{"billType":"hjres","billNumber":140,"congress":119,"govinfoText":"BILLS-119hjres140enr","publicLaw":"119-85","approvedAt":"2026-04-27","disapprovedRule":"88 FR 6308"}'::jsonb)
    RETURNING id INTO m_119_h_j_res_140;
  END IF;
  IF m_119_h_j_res_140 IS NULL THEN
    RAISE EXCEPTION 'Federal wave F3: H.J.Res. 140 could not be created or read back.';
  END IF;

  -- ── roll calls and member votes ───────────────────────────────────────────
  -- Chamber XML is the vote. congress.gov actions were used only to find the roll numbers;
  -- every tally, party split and member position below was read out of the chamber's own
  -- roll-call document — senate.gov LIS for the two Senate rolls, the House Clerk's EVS XML
  -- for the House roll — and re-verified field by field by the seed builder, which refuses
  -- to write a partial seed. Attribution is fail-closed and asymmetric by chamber, because
  -- the two documents publish different identifiers:
  --   SENATE: lis_member_id → bioguide → roster slug, AND independently (surname, state) →
  --   roster slug against OUR roster, with the two keys required to agree. A surname+state
  --   pair that matches no roster senator, matches two, or disagrees with the bioguide is
  --   skipped and counted under its own heading — three different facts, never merged.
  --   HOUSE: the Clerk publishes bioguide directly on every recorded-vote row, so the
  --   bioguide IS the key and no second key exists to cross-check it against.
  -- A member who does not resolve is skipped and counted. None is ever guessed.

  -- senate 119/1 roll 238 · S.J.Res. 7 · On the Joint Resolution
  --   50-38, 12 not voting (D 0-36, R 50-0, I 0-2) · passed
  --   losing side is 43.182% of the yea+nay pool — rule 11's one-tenth bar is cleared
  --   98 of 100 recorded members resolve to a roster slug; 2 skipped
  --   skipped as unmapped bioguide: H001104 (Jon Husted), H001079 (Cindy Hyde-Smith)
  --   0 surname+state matched no roster senator
  --   0 surname+state ambiguous across two roster senators
  --   0 bioguide and surname+state disagreed
  --   admitted as decisive, and decisiveWhy is null because the question form carries the argument
  --   'On the Joint Resolution' on an S.J.Res. is the single entry in rule 12's
  --   PASSAGE_FORMS. Admitted on the form alone, so no decisiveWhy is written. The sibling
  --   roll on the same resolution — senate 119/1 roll 235, 'On the Motion to Proceed',
  --   53-47, 2025-05-06 — is refused on question form under rule 8 and is recorded under
  --   declinedRollCalls.
  --   chamber vote description reads "A joint resolution providing for congressional
  --   disapproval under chapter 8 of title 5, United States Code, of the rule submitted by
  --   the Federal Communications Commission relating to "Addressing the Homework Gap
  --   Through the E-Rate Program"."
  INSERT INTO vr_rollcalls (measure_id, chamber, congress, session, roll_number, vote_date, question, action_type, result, required_majority, totals, source_url, source_label)
  VALUES (m_119_s_j_res_7, 'senate', 119, 1, 238, TIMESTAMPTZ '2025-05-08T11:18:00-04:00', 'On the Joint Resolution', 'passage', 'passed', 'simple',
    '{"yea":50,"nay":38,"present":0,"notVoting":12,"byParty":{"D":{"yea":0,"nay":36},"R":{"yea":50,"nay":0},"I":{"yea":0,"nay":2}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00238.xml', 'U.S. Senate')
