-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. That scoping is the
-- point rather than a detail: a guard written as a global count over vr_measure_issues
-- sums what the mapping lane wrote and what the seed lane wrote, collides with the
-- next wave that touches either, and then gets relaxed until it asserts nothing. Scope
-- the guard to the rows THIS file writes.
--
-- Member-vote counts assert >=, because ON CONFLICT DO NOTHING means an earlier
-- attribution path may already hold rows on a roll this pass touches. The orphan check
-- is exact: a politician_id on one of these rolls that is not in db/vr-member-map.json
-- is an attribution failure, not a rounding difference, and fail-closed attribution
-- means there should be none. Note that the converse is NOT asserted anywhere and must
-- not be: 323 of the House roll's 431 recorded members have no roster slug, which is
-- the roster being a reviewed subset of the chamber, not a bug.
--
-- The specific assertions are the things this pass exists to do. Every accepted row is
-- named with its weight, its primacy and its polarity, because this wave's whole
-- argument is about direction: broadband yea_opposes because the disapproved rule
-- funds connectivity, lands_preserve yea_opposes and lands_energy yea_supports because
-- the disapproved order protects land from leasing. A row that landed with the
-- polarity flipped would publish each senator's vote backwards, and a total would
-- average it away.
--
-- All 8 refused keys are asserted as ZEROES, because a refusal nobody can test is a
-- note, not a decision, and each one carries its own argument into its own failure
-- message rather than a shared pointer to the seed file. gov_regulation is the one
-- worth naming here: it must land on NEITHER measure, it was drafted on four live CRA
-- precedents that all carry it, and it was then MEASURED at zero rows gained and two
-- rows lost. A later pass that adds it back because the precedents have it should fail
-- on this assertion and go read the measurement. And H.R. 1069 stays at exactly zero
-- mapped rows, restated from F1 and F2 because every wave since has been told not to
-- invent a key for it.
--
-- Two assertions are deliberately GLOBAL rather than tuple-scoped, and both are
-- floors, not equalities: the number of Senate rolls sitting on a broadband PRIMARY
-- measure and on a lands_preserve PRIMARY measure. Those are the walls this wave
-- exists to clear. A floor cannot collide with a later wave's rows — more is fine —
-- but it does catch the one thing worth catching, which is somebody removing the
-- instrument and reopening the wall.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_unmapped integer;
  n_bb_senate integer;
  n_lp_senate integer;
  n_broadband_m_119_s_j_res_7 integer;
  n_lands_preserve_m_119_h_j_res_140 integer;
  n_lands_energy_m_119_h_j_res_140 integer;
  n_own_m_119_s_j_res_7 integer;
  n_own_m_119_h_j_res_140 integer;
  n_refused_climate_action integer;
  n_refused_edu_college_cost integer;
  n_refused_energy_production integer;
  n_refused_gov_regulation integer;
  n_refused_public_schools integer;
  n_refused_rural_ag integer;
  n_refused_states_federal_power integer;
  n_refused_water integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 1::integer, 238::integer),
    ('senate'::text, 119::integer, 2::integer, 84::integer),
    ('house'::text, 119::integer, 2::integer, 38::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), mine (measure_type, congress, chamber, number) AS (VALUES
    ('resolution'::text, 119::integer, 'senate'::text, 'S.J.Res. 7'::text),
    ('resolution'::text, 119::integer, 'house'::text, 'H.J.Res. 140'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.measure_type = k.measure_type AND m.congress = k.congress
     AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'aguilar', 'alsobrooks', 'andy_harris', 'andy_kim', 'angie_craig', 'angus_king', 'aoc', 'arrington', 'ashley_moody', 'ayanna_pressley', 'banks', 'barrasso', 'bennet', 'bennie_thompson', 'blackburn', 'blumenthal', 'blunt_rochester', 'bmoore', 'boebert', 'booker', 'boozman', 'brendan_boyle', 'brian_babin', 'brian_mast', 'britt', 'bruce_westerman', 'bryan_steil', 'cantwell', 'capito', 'cassidy', 'chellie_pingree', 'chip_roy', 'chris_murphy', 'clyburn', 'collins', 'comer', 'coons', 'cortez_masto', 'cotton', 'crapo', 'crockett', 'cruz', 'cstewart', 'curtis', 'daines', 'dan_crenshaw', 'dan_goldman', 'dan_sullivan', 'deb_fischer', 'debbie_dingell', 'delauro', 'delia_ramirez', 'diana_degette', 'don_bacon', 'don_davis', 'donalds', 'duckworth', 'durbin', 'emmer', 'ernst', 'fetterman', 'fitzpatrick', 'foxx', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'garbarino', 'gillibrand', 'glenn_thompson', 'graham', 'grassley', 'greg_landsman', 'guthrie', 'hagerty', 'haley_stevens', 'hawley', 'heinrich', 'hickenlooper', 'hirono', 'hoeven', 'jake_auchincloss', 'jan_schakowsky', 'jared_golden', 'jared_huffman', 'jason_smith', 'jayapal', 'jeffries', 'jerry_moran', 'jim_himes', 'jim_jordan', 'jim_justice', 'jim_mcgovern', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'kevin_cramer', 'kevin_hern', 'khanna', 'klobuchar', 'lankford', 'lee', 'lujan', 'lummis', 'luna', 'maggie_hassan', 'maloy', 'mariannette_miller_meeks', 'marie_gluesenkamp_perez', 'mark_kelly', 'markey', 'massie', 'maxine_waters', 'maxwell_frost', 'mcclain', 'mcconnell', 'mccormick', 'meeks', 'merkley', 'michael_guest', 'mike_bost', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_rounds', 'mike_simpson', 'mike_waltz', 'moreno', 'mtg', 'mullin', 'murkowski', 'murray', 'nadler', 'nancy_mace', 'neal', 'neguse', 'omar', 'owens', 'padilla', 'pallone', 'peters', 'raja_krishnamoorthi', 'rand_paul', 'raskin', 'reed', 'rick_crawford', 'rick_larsen', 'rick_scott', 'ricketts', 'risch', 'rob_bresnahan', 'robert_garcia', 'roger_marshall', 'roger_williams', 'ron_johnson', 'rosen', 'rubio', 'ryan_mackenzie', 'sam_graves', 'sanders', 'sarah_mcbride', 'scalise', 'schatz', 'schiff', 'schmitt', 'schumer', 'scott_perry', 'seth_moulton', 'shaheen', 'sheehy', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'takano', 'tammy_baldwin', 'ted_budd', 'ted_lieu', 'tgabbard', 'thune', 'tillis', 'tim_scott', 'tina_smith', 'tlaib', 'todd_young', 'tom_cole', 'tom_suozzi', 'tommy_tuberville', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'walberg', 'warner', 'warnock', 'warren', 'welch', 'whitehouse', 'wicker', 'wyden', 'zeldin', 'zoe_lofgren'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('broadband', 'lands_energy', 'lands_preserve'))
    INTO n_rolls, n_votes, n_orphan, n_issues;

  SELECT count(*) INTO n_broadband_m_119_s_j_res_7 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate'
     AND m.number = 'S.J.Res. 7' AND i.issue_key = 'broadband'
     AND i.is_primary IS TRUE AND i.weight = 100 AND i.support_meaning = 'yea_opposes';
  SELECT count(*) INTO n_lands_preserve_m_119_h_j_res_140 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.J.Res. 140' AND i.issue_key = 'lands_preserve'
     AND i.is_primary IS TRUE AND i.weight = 90 AND i.support_meaning = 'yea_opposes';
  SELECT count(*) INTO n_lands_energy_m_119_h_j_res_140 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.J.Res. 140' AND i.issue_key = 'lands_energy'
     AND i.is_primary IS FALSE AND i.weight = 75 AND i.support_meaning = 'yea_supports';
  SELECT count(*) INTO n_own_m_119_s_j_res_7 FROM vr_rollcalls r JOIN vr_measures m ON m.id = r.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate'
     AND m.number = 'S.J.Res. 7' AND r.chamber = 'senate';
  SELECT count(*) INTO n_own_m_119_h_j_res_140 FROM vr_rollcalls r JOIN vr_measures m ON m.id = r.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.J.Res. 140' AND r.chamber = 'house';
  SELECT count(*) INTO n_refused_climate_action FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'climate_action';
  SELECT count(*) INTO n_refused_edu_college_cost FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'edu_college_cost';
  SELECT count(*) INTO n_refused_energy_production FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'energy_production';
  SELECT count(*) INTO n_refused_gov_regulation FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'gov_regulation';
  SELECT count(*) INTO n_refused_public_schools FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'public_schools';
  SELECT count(*) INTO n_refused_rural_ag FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'rural_ag';
  SELECT count(*) INTO n_refused_states_federal_power FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'states_federal_power';
  SELECT count(*) INTO n_refused_water FROM vr_measure_issues i
   WHERE i.measure_id IN (SELECT m.id FROM vr_measures m WHERE
     (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'senate' AND m.number = 'S.J.Res. 7')
     OR (m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.J.Res. 140')
   ) AND i.issue_key = 'water';
  SELECT count(*) INTO n_unmapped FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.R. 1069';
  SELECT count(*) INTO n_bb_senate FROM vr_rollcalls r
    JOIN vr_measure_issues i ON i.measure_id = r.measure_id
   WHERE r.chamber = 'senate' AND i.issue_key = 'broadband' AND i.is_primary;
  SELECT count(*) INTO n_lp_senate FROM vr_rollcalls r
    JOIN vr_measure_issues i ON i.measure_id = r.measure_id
   WHERE r.chamber = 'senate' AND i.issue_key = 'lands_preserve' AND i.is_primary;

  RAISE NOTICE 'Federal wave F3: % roll calls, % member votes, % issue mappings', n_rolls, n_votes, n_issues;
  RAISE NOTICE 'Federal wave F3: H.R. 1069 carries % mapped issue row(s)', n_unmapped;
  RAISE NOTICE 'Federal wave F3: % senate roll(s) now sit on a broadband PRIMARY measure, % on a lands_preserve PRIMARY measure', n_bb_senate, n_lp_senate;
  RAISE NOTICE 'Federal wave F3: S.J.Res. 7 carries % roll call(s) in its own chamber (senate)', n_own_m_119_s_j_res_7;
  RAISE NOTICE 'Federal wave F3: H.J.Res. 140 carries % roll call(s) in its own chamber (house)', n_own_m_119_h_j_res_140;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % climate_action row(s) — READ AND REFUSED, so this must be 0', n_refused_climate_action;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % edu_college_cost row(s) — READ AND REFUSED, so this must be 0', n_refused_edu_college_cost;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % energy_production row(s) — READ AND REFUSED, so this must be 0', n_refused_energy_production;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % gov_regulation row(s) — READ AND REFUSED, so this must be 0', n_refused_gov_regulation;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % public_schools row(s) — READ AND REFUSED, so this must be 0', n_refused_public_schools;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % rural_ag row(s) — READ AND REFUSED, so this must be 0', n_refused_rural_ag;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % states_federal_power row(s) — READ AND REFUSED, so this must be 0', n_refused_states_federal_power;
  RAISE NOTICE 'Federal wave F3: this pass''s measures carry % water row(s) — READ AND REFUSED, so this must be 0', n_refused_water;

  IF n_rolls <> 3 THEN
    RAISE EXCEPTION 'Federal wave F3: expected 3 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 303 THEN
    RAISE EXCEPTION 'Federal wave F3: expected at least 303 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Federal wave F3: % member vote(s) on these rolls carry a politician_id outside db/vr-member-map.json. Attribution here is fail-closed, so this is a bug, not a roster gap.', n_orphan;
  END IF;
  IF n_issues < 3 THEN
    RAISE EXCEPTION 'Federal wave F3: expected at least 3 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_broadband_m_119_s_j_res_7 <> 1 THEN
    RAISE EXCEPTION 'Federal wave F3: the broadband w100 PRIMARY yea_opposes row on S.J.Res. 7 (119th) did not land (found % row(s)). Polarity is load-bearing here: the resolution disapproves an agency document, so a yea withdraws it, and a flipped row would publish every senator''s vote backwards.', n_broadband_m_119_s_j_res_7;
  END IF;
  IF n_lands_preserve_m_119_h_j_res_140 <> 1 THEN
    RAISE EXCEPTION 'Federal wave F3: the lands_preserve w90 PRIMARY yea_opposes row on H.J.Res. 140 (119th) did not land (found % row(s)). Polarity is load-bearing here: the resolution disapproves an agency document, so a yea withdraws it, and a flipped row would publish every senator''s vote backwards.', n_lands_preserve_m_119_h_j_res_140;
  END IF;
  IF n_lands_energy_m_119_h_j_res_140 <> 1 THEN
    RAISE EXCEPTION 'Federal wave F3: the lands_energy w75 secondary yea_supports row on H.J.Res. 140 (119th) did not land (found % row(s)). Polarity is load-bearing here: the resolution disapproves an agency document, so a yea advances it, and a flipped row would publish every senator''s vote backwards.', n_lands_energy_m_119_h_j_res_140;
  END IF;
  IF n_own_m_119_s_j_res_7 < 1 THEN
    RAISE EXCEPTION 'Federal wave F3: S.J.Res. 7 is a senate measure and carries % roll call(s) in the senate. Runbook rule 30''s second corollary: a measure whose own chamber does not appear among its rolls is almost always an ingest gap, and creating one inside the wave meant to close one is the specific failure this assertion exists to catch.', n_own_m_119_s_j_res_7;
  END IF;
  IF n_own_m_119_h_j_res_140 < 1 THEN
    RAISE EXCEPTION 'Federal wave F3: H.J.Res. 140 is a house measure and carries % roll call(s) in the house. Runbook rule 30''s second corollary: a measure whose own chamber does not appear among its rolls is almost always an ingest gap, and creating one inside the wave meant to close one is the specific failure this assertion exists to catch.', n_own_m_119_h_j_res_140;
  END IF;
  IF n_refused_climate_action <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: climate_action was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED. climate_action is ''programmes, subsidies and rules that cut emissions'' and the record''s CRA precedents on the key — H.J.Res. 88 and 89 — both struck Clean Air Act emission waivers with an explicit emissions […]', n_refused_climate_action;
  END IF;
  IF n_refused_edu_college_cost <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: edu_college_cost was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED. Read because the rule reaches libraries and because E-Rate''s siblings in the universal-service programme include a higher-education component. This rule does not: 89 Fed. Reg. 67303 reaches elementary and […]', n_refused_edu_college_cost;
  END IF;
  IF n_refused_energy_production <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: energy_production was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED, and this is the cousin refusal that keeps H.J.Res. 131''s precedent honest. 131 DOES file energy_production, at weight 75, and it wrote its reason: ''The reopened acreage is, under current law, the part of the […]', n_refused_energy_production;
  END IF;
  IF n_refused_gov_regulation <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: gov_regulation was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED, and this is the wave''s one deliberate divergence from a live corpus habit, so the argument is written out in full. Every Congressional Review Act resolution already in the record carries a gov_regulation […]', n_refused_gov_regulation;
  END IF;
  IF n_refused_public_schools <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: public_schools was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED on the key''s own scope note, which is quoted here rather than paraphrased: public_schools is ''the money and staffing of the DISTRICT system — funding formulas, teacher compensation, levy protection, and duties […]', n_refused_public_schools;
  END IF;
  IF n_refused_rural_ag <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: rural_ag was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED, and the reason is a keyword collision, which is exactly the kind of match this doctrine does not accept. rural_ag''s keyword list contains the literal string ''rural broadband'', so a keyword-driven mapper would […]', n_refused_rural_ag;
  END IF;
  IF n_refused_states_federal_power <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: states_federal_power was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED twice over. Substantively, the instrument is Congress overriding a federal agency, not a federalism instrument: no state authority is created, preempted or restored, and Minnesota is where the land is rather […]', n_refused_states_federal_power;
  END IF;
  IF n_refused_water <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: water was READ AND REFUSED on this pass''s measures and now carries % row(s). The argument it contradicts, in full in db/vr-federal-mapping-seed-f3.json: REFUSED on the key''s own scope note. water is IN for ''reducing, pricing or measuring water DEMAND'' and its OUT list names the supply side, public works, data-centre cooling and farm water rights. This resolution does […]', n_refused_water;
  END IF;
  IF n_unmapped <> 0 THEN
    RAISE EXCEPTION 'Federal wave F3: H.R. 1069 is deliberately unmapped and now carries % issue row(s). F1 refused nine candidate keys in writing, F2 re-refused them and F3 was told again not to invent one; see db/vr-federal-mapping-seed-f1.json before adding a row.', n_unmapped;
  END IF;
  IF n_bb_senate < 1 THEN
    RAISE EXCEPTION 'Federal wave F3: the Senate holds only % decisive roll(s) on a broadband PRIMARY measure. Below 1 the primary wall in stance-helpers.js reopens and every senator reads incidental on broadband again — which was the state this wave found, with 88 rows unread and one non-primary row in the whole corpus. S.J.Res. 7 is the only instrument in the 119th that closes it.', n_bb_senate;
  END IF;
  IF n_lp_senate < 1 THEN
    RAISE EXCEPTION 'Federal wave F3: the Senate holds only % decisive roll(s) on a lands_preserve PRIMARY measure, so lands_preserve is back to a House-only key and 90 senator rows go unread. H.J.Res. 140''s Senate passage roll is the only instrument in the 119th that closes it.', n_lp_senate;
  END IF;
END $$;
